// ---------------------------------------------------------------------------
// Casio LCD — generated by Dialcraft
// target: Amazfit Bip 6 (bip-6, 390×450, s)
//
// Built against the Zepp OS watchface API:
//   widgets  https://docs.zepp.com/docs/watchface/api/hmUI/widget/
//   layout   px() scales from app.json designWidth = 390
//   states   show_level = normal / AOD / edit
// Design-spec reminders: preview time 10:09:36, 2px safe edge, AOD keeps
// the pixel budget under 10% with a black background and no second hand.
// ---------------------------------------------------------------------------
import ui from '@zos/ui'
import * as zosFs from '@zos/fs'

const A = (p) => `images/${p}`

// ---- image arrays (frame order matters: digits 0-9, week 1-7) ----
const img_Weekday_c67n = [
  A('lcd/w0.png'),
  A('lcd/w1.png'),
  A('lcd/w2.png'),
  A('lcd/w3.png'),
  A('lcd/w4.png'),
  A('lcd/w5.png'),
  A('lcd/w6.png'),
]

const img_Month_c225 = [
  A('lcd/s0.png'),
  A('lcd/s1.png'),
  A('lcd/s2.png'),
  A('lcd/s3.png'),
  A('lcd/s4.png'),
  A('lcd/s5.png'),
  A('lcd/s6.png'),
  A('lcd/s7.png'),
  A('lcd/s8.png'),
  A('lcd/s9.png'),
]

const img_Hour_c439 = [
  A('lcd/b0.png'),
  A('lcd/b1.png'),
  A('lcd/b2.png'),
  A('lcd/b3.png'),
  A('lcd/b4.png'),
  A('lcd/b5.png'),
  A('lcd/b6.png'),
  A('lcd/b7.png'),
  A('lcd/b8.png'),
  A('lcd/b9.png'),
]

const img_Battery_c738 = [
  A('lcd/t0.png'),
  A('lcd/t1.png'),
  A('lcd/t2.png'),
  A('lcd/t3.png'),
  A('lcd/t4.png'),
  A('lcd/t5.png'),
  A('lcd/t6.png'),
  A('lcd/t7.png'),
  A('lcd/t8.png'),
  A('lcd/t9.png'),
]

const img_Hour_AOD_c1mj = [
  A('lcd/a0.png'),
  A('lcd/a1.png'),
  A('lcd/a2.png'),
  A('lcd/a3.png'),
  A('lcd/a4.png'),
  A('lcd/a5.png'),
  A('lcd/a6.png'),
  A('lcd/a7.png'),
  A('lcd/a8.png'),
  A('lcd/a9.png'),
]

// ---- saved choices (theme / variant): survive a restart and reach the always-on screen ----
const dcGet = (k) => {
  try { const v = Number(zosFs.readFileSync({ path: 'dc_' + k + '.txt', options: { encoding: 'utf8' } })); if (v) return v } catch (e) {}
  try { if (typeof hmFS !== 'undefined') return Number(hmFS.SysProGetInt(k)) || 0 } catch (e) {}
  return 0
}
const dcSet = (k, v) => {
  try { zosFs.writeFileSync({ path: 'dc_' + k + '.txt', data: String(v), options: { encoding: 'utf8' } }) } catch (e) {}
  try { if (typeof hmFS !== 'undefined') hmFS.SysProSetInt(k, v) } catch (e) {}
}

WatchFace({
  initView() {
    // the picked variant survives a restart (when the watch offers storage)
    let variantIdx = 0
    variantIdx = dcGet('dialcraft_variant')

    // layers with a code handle: W.<handle> is the widget, F.<handle> the picture list of a variants layer
    const W = {}
    const F = {}
    // Background (FILL_RECT)
    ui.createWidget(ui.widget.FILL_RECT, {
      x: px(0),
      y: px(0),
      w: px(390),
      h: px(450),
      color: 0x000000,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // LCD (IMG)
    const variants_0 = [A('lcd/scene.png'), A('lcd/scene-lit.png')]
    const variant_0 = ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(0),
      src: variants_0[variantIdx % variants_0.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.scene = variant_0
    F.scene = variants_0

    // Weekday (IMG_WEEK)
    ui.createWidget(ui.widget.IMG_WEEK, {
      x: px(70),
      y: px(45),
      week_en: img_Weekday_c67n,
      week_sc: img_Weekday_c67n,
      week_tc: img_Weekday_c67n,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Month (IMG_DATE)
    ui.createWidget(ui.widget.IMG_DATE, {
      month_startX: px(205),
      month_startY: px(50),
      month_zero: 1,
      month_space: px(0),
      month_align: ui.align.LEFT,
      month_follow: 0,
      month_en_array: img_Month_c225,
      month_sc_array: img_Month_c225,
      month_tc_array: img_Month_c225,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Date dot (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(271),
      y: px(50),
      src: A('lcd/dot.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Day (IMG_DATE)
    ui.createWidget(ui.widget.IMG_DATE, {
      day_startX: px(282),
      day_startY: px(50),
      day_zero: 1,
      day_space: px(0),
      day_align: ui.align.LEFT,
      day_follow: 0,
      day_en_array: img_Month_c225,
      day_sc_array: img_Month_c225,
      day_tc_array: img_Month_c225,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Hour (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(26),
      hour_startY: px(169),
      hour_zero: 1,
      hour_space: px(0),
      hour_align: ui.align.LEFT,
      hour_array: img_Hour_c439,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Blinking colon (IMG_ANIM)
    ui.createWidget(ui.widget.IMG_ANIM, {
      x: px(146),
      y: px(169),
      anim_path: 'images/anim',
      anim_prefix: 'lcd_colon',
      anim_ext: 'png',
      anim_fps: 2,
      anim_size: 2,
      repeat_count: 0,
      step: 1,
      anim_status: ui.anim_status.START,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Minute (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(170),
      minute_startY: px(169),
      minute_zero: 1,
      minute_space: px(0),
      minute_align: ui.align.LEFT,
      minute_array: img_Hour_c439,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Seconds (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      second_startX: px(298),
      second_startY: px(207),
      second_zero: 1,
      second_space: px(0),
      second_align: ui.align.LEFT,
      second_array: img_Month_c225,
      second_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Battery (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(26),
      y: px(330),
      w: px(108),
      type: ui.data_type.BATTERY,
      font_array: img_Battery_c738,
      align_h: ui.align.CENTER_H,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Steps (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(141),
      y: px(330),
      w: px(108),
      type: ui.data_type.STEP,
      font_array: img_Battery_c738,
      align_h: ui.align.CENTER_H,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Temperature (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(256),
      y: px(330),
      w: px(108),
      type: ui.data_type.WEATHER_CURRENT,
      font_array: img_Battery_c738,
      align_h: ui.align.CENTER_H,
      unit_en: A('lcd/degree.png'),
      unit_sc: A('lcd/degree.png'),
      unit_tc: A('lcd/degree.png'),
      negative_image: A('lcd/minus.png'),
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Hour AOD (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(63),
      hour_startY: px(180),
      hour_zero: 1,
      hour_space: px(0),
      hour_align: ui.align.LEFT,
      hour_array: img_Hour_AOD_c1mj,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Colon AOD (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(183),
      y: px(180),
      src: A('lcd/colon_aod.png'),
      show_level: ui.show_level.ONLY_AOD
    })

    // Minute AOD (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(207),
      minute_startY: px(180),
      minute_zero: 1,
      minute_space: px(0),
      minute_align: ui.align.LEFT,
      minute_array: img_Hour_AOD_c1mj,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // a Tap zone set to "Cycle variants" calls this
    const cycleVariants = () => {
      variantIdx = (variantIdx + 1) % Math.max(variants_0.length)
      dcSet('dialcraft_variant', variantIdx)
      variant_0.setProperty(ui.prop.SRC, variants_0[variantIdx % variants_0.length])
    }

    // ---- user code (project.userCode) ----
    // px() only takes a literal number (the build replaces it, there is no px at run time); pxv() scales a computed one
    const pxv = (n) => Math.round(n * px(1000) / 1000)
    // <illuminator>
    // Tap anywhere: the LCD shows its backlit picture for 4 seconds, then goes back. Leaving the screen (it goes off) puts it back at once.
    {
      let off = null;
      const light = (on) => { try { W.scene.setProperty(ui.prop.MORE, { x: pxv(0), y: pxv(0), src: F.scene[on ? 1 : 0] }); } catch (e) {} };
      const reset = () => { if (off) { clearTimeout(off); off = null; } light(false); };
      const press = () => { light(true); if (off) clearTimeout(off); off = setTimeout(() => { off = null; light(false); }, 4000); };
      ui.createWidget(ui.widget.BUTTON, { x: px(0), y: px(0), w: px(390), h: px(450), text: '', normal_src: A('lcd/tap.png'), press_src: A('lcd/tap.png'), click_func: press, show_level: ui.show_level.ONLY_NORMAL });
      ui.createWidget(ui.widget.WIDGET_DELEGATE, { pause_call: reset });
    }
    // </illuminator>
  },

  build() {
    this.initView()
  },
})
